+        assertTrue(invoice.text().contains("ISS retido (5%): R$ 38,99"));
+    }
+
+    @Test
+    void aForeignerGetsAnEnglishReceipt() {
+        Reservation reservation = bookAndPay(new Guest("John Smith", "john@example.com", null, null, null,
