+        ReservationReceipt receipt = service.receiptCopy(reservation.id());
+
+        assertEquals("Booking receipt", receipt.title());
+        assertTrue(receipt.text().contains("Check-in: 2027-03-10 | Check-out: 2027-03-12 | 2 nights"));
